1→use anyhow::{Context, Result, bail, ensure};
use super::{boot, inventory, loggers, model::*, mounts, preserve, services, system, transfer};

pub fn report_failure(state: &mut State, error: &anyhow::Error) -> Result<()> {
    let stop_result = if state.journal.as_ref().is_some_and(|j| j.operation == "activate") {
        services::down(state)
    } else { Ok(()) };
    let catalog = (|| -> Result<String> {
        super::fs::hash_file(&mut super::fs::secure_absolute(
10→            &std::path::Path::new(PERSISTED).join(".manifest.json"), libc::O_RDONLY)?)
    })();
    let observations = mounts::table().map(|m| m.into_iter().filter(|m| m.source.starts_with("opdbus-release:")).collect::<Vec<_>>());
    if let Some(journal) = state.journal.as_mut() {
        journal.error = Some(format!("{error:#}; stop result: {stop_result:?}; persisted catalog: {catalog:?}; actual release mounts: {observations:?}"));
        state.save()?;
    }
    boot::pending(&format!("{error:#}"))
}
pub fn finish_commit(state: &mut State) -> Result<()> {
20→    let journal = state.journal.as_ref().context("missing commit journal")?;
    ensure!(journal.committed && state.active == journal.to, "inconsistent durable commit");
    if let Some(transaction) = &journal.system { system::verify_committed(transaction)?; }
    let slot = state.active.context("committed activation has no active slot")?;
    let release = state.release(slot)?;
    for (index, target) in release.targets.iter().enumerate() {
        ensure!(mounts::visible(target)?.as_deref() == Some(release.tag(slot, index).as_str()), "committed target set is incomplete");
    }
    let hash = super::fs::hash_file(&mut super::fs::secure_absolute(
        &std::path::Path::new(PERSISTED).join(".manifest.json"), libc::O_RDONLY)?)?;
30→    ensure!(hash == release.catalog_sha256, "committed catalog differs");
    let journal = state.journal.take();
    if let Err(error) = state.save() { state.journal = journal; return Err(error); }
    boot::complete(state)
}
pub fn revert_activation(state: &mut State, resolve_stacks: bool) -> Result<()> {
    ensure!(!state.journal.as_ref().context("missing recovery journal")?.committed, "durably committed activation must be finalized, not reverted");
    services::down(state)?;
    state.journal.as_mut().context("missing recovery journal")?.allowed.clear(); state.save()?;
    boot::transition(state)?;
40→    services::reconcile_catalog(state)?;
    mounts::revert(state, resolve_stacks)?;
    preserve::apply_hooks(state, false)?;
    loggers::apply(state, false)?;
    system::revert(state)?;
    let from = state.journal.as_ref().unwrap().from;
    if let Some(slot) = from {
        let release = state.release(slot)?.clone();
        let inventory = inventory::load(&*state.root(slot)?)?;
        services::catalog(state, &release)?;
50→        services::reload_loggers(state)?;
        loggers::cleanup_created(state)?;
        services::restore(state, &inventory)?;
    } else {
        preserve::restore(state, preserve::RestorePhase::Content)?;
        preserve::restore(state, preserve::RestorePhase::Hooks)?;
        preserve::restore(state, preserve::RestorePhase::Links)?;
        services::reload_loggers(state)?;
        loggers::cleanup_created(state)?;
        preserve::restore(state, preserve::RestorePhase::Directories)?;
60→        services::restore_original(state)?;
    }
    system::cleanup_directories(state)?;
    state.journal = None; state.save()?; boot::complete(state)
}
pub fn recover(state: &mut State) -> Result<()> {
    let operation = state.journal.as_ref().context("no journal to recover")?.operation.clone();
    let result = match operation.as_str() {
        "provision" => transfer::provision_resume(state),
        "deploy" => transfer::recover_transfer(state),
70→        "activate" if state.journal.as_ref().is_some_and(|j| j.committed) => finish_commit(state),
        "activate" => revert_activation(state, true),
        _ => bail!("unknown transaction operation {operation}"),
    };
    if let Err(error) = result { report_failure(state, &error)?; return Err(error); }
    if operation != "activate" { boot::complete(state)?; }
    Ok(())
}

1→//! Adapter for the pinned downstream Btrfs quiescent-destroy ABI.
//! No userspace scan, kernel-version guess, or ordinary-delete fallback is safe.
use std::{io, os::fd::{AsRawFd, BorrowedFd}};
use uuid::Uuid;

// deploy/release/lifetime/0001-btrfs-quiescent-destroy.patch, native Linux ABI:
// _IOW(BTRFS_IOCTL_MAGIC /* 0x94 */, 255, struct ... /* 96 bytes */).
const SNAP_DESTROY_QUIESCENT: libc::c_ulong = 0x4060_94ff;

10→#[repr(C)]
struct QuiescentDestroy {
    subvolid: u64,
    fsid: [u8; 16],
    uuid: [u8; 16],
    received_uuid: [u8; 16],
    flags: u64,
    reserved: [u64; 4],
}
const _: () = assert!(std::mem::size_of::<QuiescentDestroy>() == 96);
20→
// The caller journals exact identity before this call and must close its own
// target-root descriptors/mounts first. `top` is a different root on the same
// filesystem. Source snapshots and aborted incoming roots use this same path;
// they must be read-only too (a zero received UUID is valid).
//
// The kernel holds admission closed continuously from its reference census
// through unlink. Success permanently closes the old incarnation; no userspace
// lease/Drop unlock is needed while the caller waits for the cleaner and renames
// the incoming root. Live-alias rejection precedes root unlink. Other failures
30→// can follow unlink, so recovery must reconcile identity after every error.
// The ABI reserves EBUSY/ESTALE/EROFS/EINVAL for pre-unlink rejection and maps
// all failures after root unlink starts to EIO. EIO never promises rollback.
// ENOENT is special to this checked ABI: its kernel lifetime registry includes
// orphan root objects through final free and proves the exact generation has
// no live inode aliases. Pathname absence or native cleaner completion alone
// never substitutes for that proof. A busy orphan remains admission-closed.
// ENOTTY means the required kernel is absent and must remain a hard failure.
pub fn destroy(
    top: BorrowedFd<'_>,
40→    fsid: Uuid,
    subvolid: u64,
    native_uuid: Uuid,
    received_uuid: Uuid,
) -> io::Result<()> {
    let args = QuiescentDestroy {
        subvolid,
        fsid: fsid.into_bytes(),
        uuid: native_uuid.into_bytes(),
        received_uuid: received_uuid.into_bytes(),
50→        flags: 0,
        reserved: [0; 4],
    };
    // SAFETY: the fixed-layout, fully initialized 96-byte input and borrowed
    // ioctl-capable directory descriptor remain valid throughout the syscall.
    let result = unsafe { libc::ioctl(top.as_raw_fd(), SNAP_DESTROY_QUIESCENT, &args) };
    match result {
        0 => Ok(()),
        -1 => Err(io::Error::last_os_error()),
        _ => Err(io::Error::from_raw_os_error(libc::EPROTO)),
60→    }
}

1→use anyhow::{Context, Result, ensure};
use std::{collections::BTreeSet, os::fd::AsFd, path::Path};
use super::{fs, inventory, model::*, mounts};

pub fn ready(text: &str) -> Result<()> { fs::atomic_text(Path::new(READY), text) }
pub fn pending(reason: &str) -> Result<()> {
    let reason = reason.replace(['\n', '\r'], " "); ready(&format!("recovery-pending {reason}\n"))
}
pub fn transition(state: &State) -> Result<()> {
10→    let j = state.journal.as_ref().context("transition without journal")?;
    let mut text = format!("transition {} {}\n", j.from.map_or("none", Slot::name), j.to.map_or("none", Slot::name));
    for name in &j.plan.order { text.push_str(&format!("q {name}\n")); }
    for name in &j.allowed { text.push_str(&format!("allow {name}\n")); }
    ready(&text)
}
pub fn complete(state: &State) -> Result<()> {
    if state.journal.is_some() { return pending("journal-present"); }
    let Some(slot) = state.active else { return ready("none\n"); };
    let release = state.release(slot)?;
20→    for (i, target) in release.targets.iter().enumerate() {
        if mounts::visible(target)?.as_deref() != Some(release.tag(slot,i).as_str()) { return pending("target-set-incomplete"); }
    }
    let hash = fs::hash_file(&mut fs::secure_absolute(&Path::new(PERSISTED).join(".manifest.json"), libc::O_RDONLY)?)?;
    if hash != release.catalog_sha256 { return pending("catalog-mismatch"); }
    ready(&format!("complete {} {} {}\n", slot.name(), release.name, hash))
}
pub fn run(state: &State) -> Result<()> {
    let cmdline = std::fs::read_to_string("/proc/cmdline")?;
    if cmdline.split_whitespace().any(|s| s == "opdbus.release=off") { return ready("disabled\n"); }
30→    if state.journal.as_ref().is_some_and(|j| !j.committed) {
        return pending("journal-present; explicit recovery required before boot activation");
    }
    let Some(slot) = state.active else { return ready("none\n"); };
    pending("boot-mounting-committed-set")?;
    ensure!(std::fs::read_to_string("/proc/filesystems")?.lines().any(|l| l.split_whitespace().last() == Some("overlay")), "overlay module is not preloaded; boot will not autoload it");
    let release = state.release(slot)?; let root = state.root(slot)?;
    let inventory = inventory::load(&root)?;
    ensure!(inventory.graph_sha256 == release.graph_sha256 && inventory.tree_sha256 == release.tree_sha256, "boot committed inventory mismatch");
    let base = fs::release_base()?;
40→    let mut built = Vec::new();
    for (index,target) in release.targets.iter().enumerate() {
        let parent = mounts::verify_parent(target)?;
        if let Some(tag) = mounts::visible(target)? {
            ensure!(tag == release.tag(slot,index), "boot will not replace an uncommitted/foreign target"); continue;
        }
        let target_fd = fs::secure_absolute(&target.path, libc::O_PATH | libc::O_DIRECTORY)?;
        ensure!(fs::mount_id(target_fd.as_fd())? == parent.mount_id, "boot target parent mount mismatch");
        let lower = fs::open_beneath(root.as_fd(), &target.source, libc::O_RDONLY | libc::O_DIRECTORY)?;
        let overlay = fs::detached_overlay(lower.as_fd(), base.as_fd(), &release.tag(slot,index), target.noexec)?;
50→        built.push((index, overlay, target_fd));
    }
    for (index, overlay, target) in built {
        // Boot intentionally does not mutate durable state or recover the transaction.
        pending(&format!("boot-place-{index}"))?;
        fs::place(overlay.as_fd(), target.as_fd(), false)?;
    }
    complete(state)
}

1→use anyhow::{Context, Result, ensure};
use sha2::{Digest, Sha256};
use std::{fs::File, os::{fd::AsFd, unix::fs::{MetadataExt, PermissionsExt}}, path::{Path, PathBuf}};
use super::{fs, inventory::Inventory, model::*, preserve, services};

const DISABLED: &str = ".op-release-disabled-log";
fn base(name: &str) -> PathBuf { Path::new(SERVICES).join(name) }
fn present(path: &Path) -> Result<bool> {
    match std::fs::symlink_metadata(path) {
10→        Ok(metadata) => { ensure!(metadata.is_dir(), "logger location is not a real directory: {}", path.display()); Ok(true) },
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(false),
        Err(error) => Err(error.into()),
    }
}
fn identity(path: &Path) -> Result<(String, u64, u64)> {
    let parent = fs::secure_absolute(path.parent().unwrap(), libc::O_RDONLY | libc::O_DIRECTORY)?;
    let root = fs::secure_absolute(path, libc::O_RDONLY | libc::O_DIRECTORY)?;
    let subvolume = btrfs_uapi::subvolume::subvolume_info(root.as_fd())?;
    ensure!(root.metadata()?.ino() != 256 && fs::mount_id(root.as_fd())? == fs::mount_id(parent.as_fd())?
20→        && subvolume.id == btrfs_uapi::subvolume::subvolume_info(parent.as_fd())?.id,
        "logger preservation must remain in the same parent subvolume");
